/* ── the curtains: real satin panels, redrawn row by row so the pleats gather into the tie-backs ── */
const hero = $("hero"), cur = $("cur"), cc = cur.getContext("2d");
let CW = 0, CH = 0, DPR = 1, curP = 0, valP = 0, ready = false;
const IMG = {}, A = "/assets/cinorev/garden-curtains/a/";
const load = n => new Promise(r => { const i = new Image(); i.onload = () => { IMG[n] = i; r(); }; i.onerror = () => r(); i.src = A + n + ".webp"; });
const assets = Promise.all(["cur-l", "cur-r", "valance", "tieback"].map(load)).then(() => { ready = true; sizeCurtain(); });
let TIE = .6; const VSCALE = 1;
function tieY(){ return TIE; }
function measureTie(){
  const g = $("gside-l"), h = g ? g.getBoundingClientRect().height : 0;
  TIE = h && CH ? Math.max(.36, Math.min(.6, (CH - h * .91) / CH - .07)) : .6;
}
function innerX(ny, p){
  const ty = tieY(), closed = .5;
  let open;
  if (ny <= ty) { const t = Math.max(0, (ny - .06) / (ty - .06)); open = .11 + .21 * Math.pow(1 - t, 1.5); }
  else { const t = (ny - ty) / (1 - ty); open = .11 + .09 * Math.pow(t, .75); }
  const delay = .26 * Math.abs(ny - ty) / .6, e = Math.min(1, Math.max(0, (p - delay) / (1 - .26)));
  const k = e < .5 ? 4 * e * e * e : 1 - Math.pow(-2 * e + 2, 3) / 2;
  return closed + (open - closed) * k;
}
function sizeCurtain(){
  const r = hero.getBoundingClientRect(); DPR = Math.min(2, devicePixelRatio || 1); CW = r.width; CH = r.height;
  cur.width = Math.round(CW * DPR); cur.height = Math.round(CH * DPR);
  measureTie(); drawCurtain(curP);
}
function drawCurtain(p){
  if (!ready) return;
  const k = cc; k.setTransform(DPR, 0, 0, DPR, 0, 0); k.clearRect(0, 0, CW, CH);
  const L = IMG["cur-l"], R = IMG["cur-r"];
  const rows = Math.ceil(CH / 3), rh = CH / rows, edge = [];
  for (let i = 0; i <= rows; i++) { const y = i * rh; edge.push([innerX(y / CH, p) * CW, y]); }
  /* soft shadow cast by each panel onto the garden */
  if (p > 0) [0, 1].forEach(side => {
    k.save(); k.beginPath(); k.moveTo(side ? CW : 0, 0);
    edge.forEach(([x, y]) => k.lineTo(side ? CW - x : x, y));
    k.lineTo(side ? CW : 0, CH); k.closePath();
    k.shadowColor = "rgba(80,50,35,.4)"; k.shadowBlur = 24; k.shadowOffsetX = side ? -6 : 6; k.fillStyle = "#E7D6C2"; k.fill(); k.restore();
  });
  /* the satin, row by row */
  const sl = L.naturalHeight / CH, sr = R.naturalHeight / CH;
  for (let i = 0; i < rows; i++) {
    const x = edge[i][0], y = edge[i][1];
    k.drawImage(L, 0, y * sl, L.naturalWidth, rh * sl, 0, y, x + .6, rh + .6);
    k.drawImage(R, 0, y * sr, R.naturalWidth, rh * sr, CW - x - .6, y, x + .6, rh + .6);
  }
  /* a touch of shade where the satin is gathered */
  if (p > 0) {
    const ty = tieY() * CH, g = k.createRadialGradient(0, ty, 0, 0, ty, CW * .28);
    g.addColorStop(0, "rgba(90,60,40," + (.22 * p).toFixed(3) + ")"); g.addColorStop(1, "rgba(90,60,40,0)");
    k.save(); k.globalCompositeOperation = "source-atop"; k.fillStyle = g; k.fillRect(0, 0, CW * .4, CH);
    const g2 = k.createRadialGradient(CW, ty, 0, CW, ty, CW * .28); g2.addColorStop(0, "rgba(90,60,40," + (.22 * p).toFixed(3) + ")"); g2.addColorStop(1, "rgba(90,60,40,0)");
    k.fillStyle = g2; k.fillRect(CW * .6, 0, CW * .4, CH); k.restore();
  }
  /* tie-backs: the pearl rope wraps the gathered satin, the tassel hangs below */
  const tie = Math.min(1, Math.max(0, (p - .6) / .4)), T = IMG.tieback;
  if (tie > 0 && T) {
    const ty = tieY() * CH, tx = innerX(tieY(), 1) * CW, th = Math.min(CH * .2, CW * .42), tw = th * T.naturalWidth / T.naturalHeight;
    k.save(); k.globalAlpha = tie; k.shadowColor = "rgba(60,40,25,.35)"; k.shadowBlur = 8; k.shadowOffsetY = 4;
    k.drawImage(T, tx * .52 - tw / 2, ty - th * .5, tw, th);
    k.drawImage(T, CW - tx * .52 - tw / 2, ty - th * .5, tw, th);
    k.restore();
  }
  /* the valance: it drops in from above once the curtains have parted, and settles softly like fabric */
  const V = IMG.valance;
  if (V && valP > 0) {
    const vh = CW * V.naturalHeight / V.naturalWidth * VSCALE, u = Math.min(1, valP);
    const c1 = 1.25, e = 1 + (c1 + 1) * Math.pow(u - 1, 3) + c1 * Math.pow(u - 1, 2);     /* ease-out with a small settle */
    const y = -(1 - e) * vh * 1.08, sq = 1 + Math.max(0, e - 1) * .35;                   /* a touch of stretch as it lands */
    k.save(); k.globalAlpha = Math.min(1, u * 3); k.shadowColor = "rgba(60,40,25," + (.3 * u).toFixed(3) + ")"; k.shadowBlur = 12; k.shadowOffsetY = 6;
    k.drawImage(V, 0, y, CW, vh * sq); k.restore();
  }
}
function openCurtain(dur){
  /* the curtains part and tie back; near the end the valance falls into place */
  const vStart = dur * .72, vDur = 1300;
  return new Promise(res => {
    if (calm) { curP = 1; valP = 1; drawCurtain(1); res(); return; }
    const t0 = performance.now(); let swished = false;
    (function f(now){
      const t = now - t0; curP = Math.min(1, t / dur); valP = Math.max(0, Math.min(1, (t - vStart) / vDur));
      if (valP > 0 && !swished) { swished = true; noise(0, 1.1, "bandpass", 1400, .6, .06, 500); }
      drawCurtain(curP);
