const wait = ms => new Promise(r => setTimeout(r, ms));
const pic = src => new Promise(r => { const i = new Image(); i.onload = i.onerror = () => r(); i.src = src; });
const scene = Promise.all(["garden-sunset", "garden-left", "garden-right"].map(n => pic(A + n + ".webp")));
function fontsFor(sel){
