/* names stay on one line: shrink a little if the screen is narrow */
function fitAll(){ document.querySelectorAll("[data-fit]").forEach(e => { e.style.fontSize = ""; let fs = parseFloat(getComputedStyle(e).fontSize); while (e.scrollWidth > e.clientWidth + 1 && fs > 16) { fs -= 1; e.style.fontSize = fs + "px"; } }); }
