/* confetti: deep green, sage, gold and white */
const cv = $("fx"), cx = cv.getContext("2d");
let bits = [], fxRun = false, fxLast = 0;
function sizeFx(){ const d = Math.min(2, devicePixelRatio || 1); cv.width = innerWidth * d; cv.height = innerHeight * d; cx.setTransform(d, 0, 0, d, 0, 0); }
sizeFx(); addEventListener("resize", sizeFx);
const COLS = ["#2F3B2A", "#2F3B2A", "#46553B", "#3B3532", "#6E7B58", "#98A37E"];
function rain(n, spread){
  if (calm) return;
  for (let i = 0; i < n; i++) bits.push({ x: Math.random() * innerWidth, y: -10 - Math.random() * (spread || innerHeight * .35), vx: (Math.random() - .5) * 30, vy: 150 + Math.random() * 120, vt: 230 + Math.random() * 110, c: COLS[Math.floor(Math.random() * COLS.length)], k: Math.random() < .22 ? "streak" : "dot", r: Math.random() * 6.3, vr: (Math.random() - .5) * 5, s: 1.2 + Math.random() * 2, ph: Math.random() * 6.3 });
  if (bits.length > 500) bits.splice(0, bits.length - 500);
  if (!fxRun) { fxRun = true; fxLast = performance.now(); requestAnimationFrame(step); }
}
function burst(x, y, n, power){
  if (calm) return;
  for (let i = 0; i < n; i++) {
    const a = -Math.PI / 2 + (Math.random() - .5) * 2.8, s = power * (.35 + Math.random() * .75);
    bits.push({ x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s, c: COLS[Math.floor(Math.random() * COLS.length)], k: Math.random() < .18 ? "streak" : "dot", r: Math.random() * 6.3, vr: (Math.random() - .5) * 8, s: 2.2 + Math.random() * 3, ph: Math.random() * 6.3 });
  }
