  if (!fxRun) { fxRun = true; fxLast = performance.now(); requestAnimationFrame(step); }
}
function step(t){
  const dt = Math.min(.033, (t - fxLast) / 1000); fxLast = t;
  cx.clearRect(0, 0, innerWidth, innerHeight);
  bits = bits.filter(b => b.y < innerHeight + 30);
  for (const b of bits) {
    b.vy = Math.min(b.vy + 420 * dt, Math.max(120, b.vt || 0)); b.vx *= .985;
    b.x += (b.vx + Math.sin(t / 400 + b.ph) * 24) * dt; b.y += b.vy * dt; b.r += b.vr * dt;
    cx.save(); cx.translate(b.x, b.y); cx.rotate(b.r); cx.fillStyle = b.c; cx.strokeStyle = b.c;
    if (b.k === "dot") { cx.scale(1, Math.cos(b.r) * .4 + .7); cx.beginPath(); cx.arc(0, 0, b.s, 0, 6.3); cx.fill(); }
    else { cx.lineWidth = 1.4; cx.beginPath(); cx.moveTo(-b.s * 2.2, 0); cx.lineTo(b.s * 2.2, 0); cx.stroke(); }
    cx.restore();
