}

/* scratch the heart: sage glitter over the date */
const sh = $("sh"), sc = $("scr"), sk = sc.getContext("2d"), scratch = $("scratch");
let heartPath, revealed = false, scratching = false, lastPt = null, scrW = 0, scrH = 0, checkT = 0, samples = [];
const glitter = new Image(); glitter.onload = () => { if (!revealed) paintGlitter(); }; glitter.src = A + "glitter.webp";
function heart(w, h){ const p = new Path2D(); p.addPath(new Path2D("M50 90C22 70 2 52 2 28 2 12 14 2 28 2c10 0 18 6 22 14C54 8 62 2 72 2c14 0 26 10 26 26 0 24-20 42-48 62Z"), new DOMMatrix().scale(w / 100, h / 92)); return p; }
function paintGlitter(){
